    # Return the longest palindromic substring using expand around center O(n^2)
    n = len(s)
    if n == 0:
        return ""
    best = (0, 0)  # (start, length)
    def expand(left, right):
        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1  # start, length
    for i in range(n):
        # odd length
        start, length = expand(i, i)
        if length > best[1]:
            best = (start, length)
        # even length
        start, length = expand(i, i+1)
        if length > best[1]:
            best = (start, length)
    return s[best[0]:best[0]+best[1]]"}

