def solve(coins, amount):
    # DP for unbounded knapsack (minimum coins)
    # Initialize DP array with amount+1 (as infinity)
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

