def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D grid.
    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0])
    visited = [[False] * m for _ in range(n)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(si, sj):
        stack = [(si, sj)]
        visited[si][sj] = True
        while stack:
            i, j = stack.pop()
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    stack.append((ni, nj))

    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

