{"task_id": "T25", "code": "def solve(matrix):
    """Return the determinant of a square matrix of integers.
    Uses the Bareiss algorithm (fraction-free Gaussian elimination) which
    works exactly with integer arithmetic and avoids overflow for typical
    input sizes in these challenges.
    If the matrix is empty, returns 1 (determinant of 0x0 matrix).
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy to avoid mutating input
    A = [list(row) for row in matrix]
    det = 1
    for k in range(n-1):
        # Find pivot
        if A[k][k] == 0:
            # Search for a non-zero pivot and swap rows
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // (A[k-1][k-1] if k > 0 else 1)
            A[i][k] = 0
    det *= A[n-1][n-1]
    return det"}

