    # Handle edge cases
    if capacity <= 0 or not weights:
        return 0
    # Ensure all weights are positive integers; if weight is zero, we can add its value once
    dp = [0] * (capacity + 1)
    for wt, val in zip(weights, values):
        if wt <= 0:
            # weight zero: add value to all capacities (once)
            for w in range(capacity + 1):
                dp[w] += val
            continue
        for w in range(capacity, wt - 1, -1):
            new_val = dp[w - wt] + val
            if new_val > dp[w]:
                dp[w] = new_val
