{"task_id": "T25", "code": "def solve(matrix):
    """Return the determinant of a square matrix of integers.
    Uses the Bareiss fraction‑free Gaussian elimination algorithm, which
    computes the exact integer determinant without overflow for typical
    challenge sizes. An empty matrix (0×0) has determinant 1 by definition.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a mutable copy
    A = [list(row) for row in matrix]
    det_sign = 1
    # Bareiss algorithm
    for k in range(n - 1):
        # Pivot handling: if zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0  # singular matrix
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]"}

