    """0/1 knapsack: maximum total value with total weight <= capacity.
    Handles items with zero weight by including their values (they can always be taken).
    """
    # Sum values of zero-weight (or negative-weight) items; they don't affect capacity.
    base_value = 0
    pos_items = []  # items with positive weight <= capacity
    for w, v in zip(weights, values):
        if w <= 0:
            base_value += v
        elif w <= capacity:
            pos_items.append((w, v))
        # items heavier than capacity are ignored
    # If capacity is non-positive, we cannot take any positive-weight items.
    if capacity <= 0:
        return base_value
    dp = [0] * (capacity + 1)
    for w, v in pos_items:
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity] + base_value
