def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    - Collapse multiple '/' into one.
    - Resolve '.' (current directory) and '..' (parent directory).
    - Keep leading '/' for absolute path. The root is '/' if resulting stack empty.
    """
    if not isinstance(path, str):
        return ''
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified

