def solve(matrix):
    """Return the determinant of a square integer matrix using Bareiss algorithm.
    Empty matrix returns 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    a = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        if a[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[...]
            det = -det
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // (a[k-1][k-1] if k>0 else 1)
            a[i][k] = 0
    return det * a[n-1][n-1]

