def solve(line):
    """Parse a single CSV line into fields.
    Handles optional double‑quote quoting. Inside quoted fields commas are
    literal and a pair of double quotes represents a literal quote.
    An empty line yields a list containing a single empty string.
    """
    fields = []
    field = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i+1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field))
                field = []
            elif ch == '"':
                in_quotes = True
            else:
                field.append(ch)
        i += 1
    # Append last field (including case of empty line)
    fields.append(''.join(field))
    return fields

