def solve(intervals):
    if not intervals:
        return []
    # sort intervals by start
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for cur in intervals[1:]:
        prev = merged[-1]
        # if overlapping or touching
        if cur[0] <= prev[1]:
            prev[1] = max(prev[1], cur[1])
        else:
            merged.append(cur[:])
    return merged

